INSERT INTO bugs (id, project_code, title, module_id, severity, category, details, status, reported_by, assigned_to, reported, resolved) VALUES
  ('BUG-001', 'PRJ-2025-014', 'Lab result not auto-posting to EMR', 'M-EMR', 'Medium', 'Integration', 'Lab result not auto-posting to EMR. Found on the EMR / Clinicals module during client UAT. Medium severity — requires scheduled fix and retest before sign-off.', 'Retest', 'Client UAT', 'Vikram Menon', '2026-07-27', NULL),
  ('BUG-002', 'PRJ-2025-014', 'Bed status not refreshing after transfer', 'M-EMR', 'High', 'Security', 'Bed status not refreshing after transfer. Found on the EMR / Clinicals module during client UAT. High severity — requires scheduled fix and retest before sign-off.', 'In Progress', 'Client UAT', 'Vikram Menon', '2026-06-12', NULL),
  ('BUG-003', 'PRJ-2025-014', 'Insurance co-pay calc incorrect', 'M-INS', 'Low', 'UI / UX', 'Insurance co-pay calc incorrect. Found on the Insurance / TPA module during client UAT. Low severity — requires scheduled fix and retest before sign-off.', 'Retest', 'Client UAT', 'Vikram Menon', '2026-04-20', NULL),
  ('BUG-004', 'PRJ-2025-009', 'Pharmacy stock going negative', 'M-OT', 'Low', 'UI / UX', 'Pharmacy stock going negative. Found on the Operation Theatre module during client UAT. Low severity — requires scheduled fix and retest before sign-off.', 'Closed', 'Client UAT', 'Sana Qureshi', '2026-04-20', '2026-06-19'),
