INSERT INTO process_flows (id, integration_id, process_name, business_rules, exception_cases) VALUES
  (1, 'INT-01', 'M-Pesa Payment Collection', 'Amount must match invoice balance. Duplicate CheckoutRequestID rejected. Timeout after 120s triggers reconciliation query.', 'User cancels STK prompt · insufficient funds · callback not received (poll STK status) · duplicate transaction.'),
  (2, 'INT-03', 'NHIF Claim Submission', 'Member must be active. ICD-10 diagnosis mandatory. Pre-auth required above KES 50,000.', 'Member inactive · policy expired · duplicate claim · service not covered.'),
  (3, 'INT-05', 'NBC Bank Collection', 'Reference expires in 72h. Partial payments allowed. Settlement file pulled daily 06:00.', 'Reference expired · under/over payment · callback mismatch · settlement gap.'),
  (4, 'INT-07', 'PACS Study Exchange', 'Accession number unique per order. Study auto-linked by MRN + accession.', 'Worklist not received · orphan study · report delayed.');
