INSERT INTO developer_notes (id, integration_id, code_location, important_notes, common_errors, debugging_steps, deployment_steps) VALUES
  ('DN-01', 'INT-01', 'HIMS.API > Payment/Mpesa > MpesaGateway.cs', 'Token valid 3599s — cache it. Password = Base64(Shortcode+Passkey+Timestamp).', '404.001 invalid token · 500.001.1001 duplicate · callback not hitting (check public URL).', 'Log MerchantRequestID. Use STK Query when callback missing. Verify CallBackURL is HTTPS & reachable.', 'Set Shortcode/Passkey/ConsumerKey/Secret in appsettings. Whitelist callback IP. Run DB script.'),
  ('DN-02', 'INT-03', 'HIMS.API > Insurance/Nhif > NhifService.cs', 'HospitalCode + FacilityCode mandatory in every header. ICD-10 required for claims.', '401 expired key · 404 member not found · 409 policy expired.', 'Check member status first. Validate ICD-10 before submit. Inspect ClaimReference in response.', 'Configure API key + hospital/facility codes per client. Whitelist facility with NHIF.'),
  ('DN-03', 'INT-05', 'HIMS.API > Banking/Nbc > NbcGateway.cs', 'Control number expires in 72h. Settlement file pulled daily 06:00 by scheduler.', '409 duplicate reference · settlement mismatch · callback signature invalid.', 'Verify HMAC signature on callback. Reconcile against settlement statement.', 'Set Client-ID/Secret. Configure settlement account. Enable job_NbcSettlement.');
