  ('FEA-1001', 'Insurance Card Integration', 'Insurance / TPA', 'Revenue', 'ABC Hospital', '2026-05-20', 'High', '18 days', 'In Development', 9.4, 1, 5200000, 850000, 34, 41, 12, 4.6, 88, 62, 'Anita Rao', 'Devendra Singh', 'Utkarsh', 'Dr. Mehta (ABC)', 'Manual insurance card entry causes errors and slows OPD billing.', 'Scan/parse insurance card, auto-fill member & scheme, verify eligibility in real time.'),
  ('FEA-1002', 'AI-Based OPD Queue Prediction', 'AI / Automation', 'Efficiency', 'City Hospital', '2026-05-18', 'High', '30 days', 'Under Review', 8.8, 1, 0, 1200000, 0, 0, 0, 0, 0, 0, 'Sneha Rao', 'Devendra Singh', 'TBD', 'Admin (City)', 'Unpredictable OPD wait times hurt patient satisfaction.', 'ML model predicts queue length & wait time; display on token screens.'),
  ('FEA-1003', 'WhatsApp Appointment Reminder', 'Patient Engagement', 'Patient Experience', 'XYZ Hospital', '2026-05-19', 'Medium', '8 days', 'Testing', 8.2, 1, 2100000, 260000, 58, 64, 6, 4.8, 92, 78, 'Neha Patel', 'Devendra Singh', 'Shubham', 'Front Office (XYZ)', 'High no-show rate for booked appointments.', 'Send WhatsApp reminders 24h & 2h before appointment with confirm/reschedule.'),
  ('FEA-1004', 'Auto Split Billing', 'Billing', 'Revenue', 'Life Care Hospital', '2026-05-17', 'Medium', '12 days', 'Deployed', 7.6, 1, 3800000, 420000, 21, 27, 9, 4.4, 81, 55, 'Anita Rao', 'Devendra Singh', 'Utkarsh', 'Billing Head (Life Care)', 'Splitting a bill between insurance & patient is manual and error-prone.', 'Rule-based auto split of charges across payer + patient with configurable ratios.'),
  ('FEA-1005', 'Dynamic Consent Form', 'Clinical / EMR', 'Compliance', 'Sunrise Hospital', '2026-05-16', 'Low', '10 days', 'Approved', 6.9, 1, 900000, 300000, 8, 11, 2, 4.3, 70, 33, 'Sneha Rao', 'Devendra Singh', 'Priya', 'Compliance (Sunrise)', 'Paper consent forms are hard to audit and localise.', 'Configurable digital consent templates with e-signature & audit trail.'),
  ('FEA-1006', 'Patient Self Check-in Kiosk', 'Patient Engagement', 'Patient Experience', 'Prime Hospital', '2026-05-12', 'High', '22 days', 'Deployed', 7.2, 1, 2600000, 560000, 17, 20, 7, 4.5, 76, 48, 'Neha Patel', 'Devendra Singh', 'Shubham', 'Ops (Prime)', 'Front-desk congestion at peak OPD hours.', 'Kiosk self check-in with token print & payment.'),
  ('FEA-1007', 'Lab Result Auto SMS', 'Laboratory', 'Automation', 'City Hospital', '2026-04-28', 'Medium', '5 days', 'Available for All', 7, 1, 1400000, 180000, 72, 80, 4, 4.7, 90, 82, 'Neha Patel', 'Devendra Singh', 'Shubham', 'Lab (City)', 'Patients call repeatedly asking if reports are ready.', 'Auto SMS/WhatsApp with secure report link when lab result is verified.'),
  ('FEA-1008', 'ePrescription Module', 'Clinical / EMR', 'Efficiency', 'Medicare Hospital', '2026-04-20', 'High', '25 days', 'Available for All', 8.1, 1, 4100000, 720000, 61, 70, 15, 4.5, 85, 74, 'Sneha Rao', 'Devendra Singh', 'Utkarsh', 'Dr. Rao (Medicare)', 'Handwritten prescriptions cause dispensing errors.', 'Structured ePrescription with drug interaction check & pharmacy hand-off.'),
  ('FEA-1009', 'Telemedicine Module', 'Clinical / EMR', 'Revenue', 'Health Plus', '2026-04-15', 'High', '35 days', 'In Development', 8.5, 1, 3300000, 1400000, 9, 12, 8, 4.2, 72, 28, 'Sneha Rao', 'Devendra Singh', 'Utkarsh', 'CEO (Health Plus)', 'No remote consultation channel post-pandemic demand.', 'Video consult with scheduling, e-prescription and online payment.'),
  ('FEA-1010', 'Payroll Integration', 'Administration', 'Integration', 'Prime Hospital', '2026-04-10', 'Low', '15 days', 'Deployed', 6.4, 0, 700000, 380000, 3, 3, 3, 4, 58, 12, 'Priya Menon', 'Devendra Singh', 'Priya', 'HR (Prime)', 'Manual payroll export to accounting.', 'Sync attendance & payroll to finance ledger.'),
