INSERT INTO feature_business_analysis (feature_id, objective, existing_workflow, new_workflow, benefits, functional_req, non_functional_req, dependencies, assumptions) VALUES
  ('FEA-1001', 'Cut OPD registration time and insurance rejections.', 'Front desk types insurance details manually → error-prone eligibility check by phone.', 'Scan card → auto-fill → real-time eligibility → proceed to cashless billing.', 'Faster registration, fewer claim rejections, better cashless experience.', 'Card OCR, eligibility API, scheme auto-map, exception queue.', 'Eligibility response < 3s, PII encrypted at rest.', 'Insurance/TPA API (SIR), OCR service.', 'Insurer exposes eligibility API; card format standardised.'),
  ('FEA-1003', 'Reduce appointment no-shows.', 'Manual reminder calls by front office.', 'System auto-sends WhatsApp reminders with confirm/reschedule buttons.', 'Higher show-up rate, lower staff effort, better patient experience.', 'Template management, opt-in, delivery tracking, reschedule link.', 'Message delivery within 30s; GDPR/consent compliant.', 'WhatsApp Business API (SIR).', 'Patient mobile numbers valid & opted-in.'),
  ('FEA-1004', 'Eliminate manual split errors and speed up billing.', 'Cashier manually splits charges between payer and patient.', 'Rule engine auto-splits charges by configured payer ratios.', 'Accurate splits, faster billing, cleaner claims.', 'Split rules per scheme, override with reason, audit trail.', 'Deterministic rounding; fully auditable.', 'Insurance scheme master.', 'Payer ratios known per scheme.');
INSERT INTO feature_technical_analysis (feature_id, db_changes, tables, stored_procs, apis, background_jobs, reports, mobile_changes, portal_changes) VALUES
  ('FEA-1001', 'Add InsuranceCardScan table; extend PatientInsurance.', 'InsuranceCardScan, PatientInsurance', 'usp_SaveCardScan, usp_VerifyEligibility', 'POST /insurance/eligibility, POST /ocr/card', 'job_RetryEligibility (5 min)', 'Insurance Rejection Report', 'Card scan in patient app', 'Insurance panel on registration'),
  ('FEA-1003', 'Add AppointmentReminder table.', 'AppointmentReminder', 'usp_QueueReminder', 'POST /wa/send', 'job_SendReminders (hourly)', 'No-show Trend Report', '—', 'Reminder settings'),
  ('FEA-1004', 'Add BillSplitRule table; extend Invoice.', 'BillSplitRule, Invoice', 'usp_ApplySplitRule', 'POST /billing/split', '—', 'Payer Split Report', '—', 'Split preview on invoice');
INSERT INTO feature_workflows (feature_id, decision_points, alternate_flows, exception_handling) VALUES
  ('FEA-1001', 'Eligible? → cashless. Not eligible → cash / exception queue.', 'Manual entry if scan fails.', 'Eligibility timeout → retry job; card OCR low-confidence → manual review.'),
  ('FEA-1004', 'Scheme configured? → auto-split. Else → manual.', 'Manual override with reason.', 'Rounding mismatch → adjust to patient share; missing rule → block with alert.');
